import json

def extract_body_literals(text, topic):
    literals = []
    words = text.split()

    # Preprocess text to remove stop words and punctuation
    # For simplicity, this example does not handle complex grammar
    for word in words:
        clean_word = word.strip(".,!?:;")
        clean_word = clean_word.lower()

        if clean_word in ["the", "a", "an", "and", "is", "are", "for", "it", "with", "on", "at", "by", "from"]:
            continue

        # Simple literal extraction
        if clean_word in ["unbearable", "no", "not", "none", "nonexistent", "non", "un"]:
            literals.append(clean_word)
        elif clean_word.endswith("able") or clean_word.endswith("ible"):
            literals.append(clean_word)
        elif clean_word.endswith("less") or clean_word.endswith("more"):
            literals.append(clean_word)

    # Manual mapping for given problem
    mapping = {
        "unbearable": "unbearable_room",
        "no": "no_simple_sheets_room",
        "not": "not_usable_hair_dryer",
        "none": "no_soundproofing_windows"
    }

    result = []
    for literal in literals:
        if literal in mapping:
            result.append(mapping[literal])
        else:
            result.append(literal + "_room")

    return json.dumps({"body_literals": result})

