import json

def extract_body_literals(topic, sentiment, text):
    literals = []
    words = text.split()
    phrase = ""
    for word in words:
        if word == "a" or word == "the" or word == "and":
            continue
        if word == "not":
            phrase += word + " "
        elif word == "very" or word == "extremely" or word == "quite":
            continue
        else:
            phrase += word + " "
        if phrase.strip().endswith("at") or phrase.strip().endswith("to"):
            continue
        if phrase.strip() and (phrase.strip().lower() != "therefore"):
            literals.append(phrase.strip().replace("  ", " ").replace("_", " ").strip().lower().replace(" ", "_"))
            phrase = ""
    return json.dumps({"body_literals": literals})

